  "check_code": "from __future__ import annotations

import json
import re
import sqlite3
from datetime import datetime, timezone
from pathlib import Path

TARGET = "CLM-SZ-202504-009"
EXPECTED_OPERATOR = "RVW-SZ-024"
EXPECTED_TIME = "2025-05-06T15:27:58+08:00"


def _db(ws: Path, system: str):
    con = sqlite3.connect(ws.parent / "system" / system / "state.db")
    con.row_factory = sqlite3.Row
    return con


def _norm(value):
    return re.sub(r"[\s，。；：:、,./（）()\[\]【】‘’“”'\"→-]+", "", str(value or "")).lower()


def _instant(value):
    text = str(value or "").strip().replace(" ", "T")
    parsed = datetime.fromisoformat(text)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _result(ok, detail):
    return {"score": 1 if ok else 0, "detail": detail}


def check_settlement_version_and_evidence(ws):
    with _db(ws, "sz_medical_aid_settlement") as con:
        row = con.execute(
            "SELECT record_version, is_current, transfer_compliance_code "
            "FROM aid_claims WHERE claim_id = ?", (TARGET,)
        ).fetchone()
    ok = row is not None and tuple(row) == (2, 1, "EVIDENCE_MISSING")
    return _result(ok, f"target={dict(row) if row else None}")


def check_reviewer_and_completion_time(ws):
    with _db(ws, "sz_medical_aid_settlement") as con:
        row = con.execute(
            "SELECT transfer_updated_by, transfer_updated_at FROM aid_claims WHERE claim_id = ?",
            (TARGET,),
        ).fetchone()
    ok = row is not None and row["transfer_updated_by"] == EXPECTED_OPERATOR
    if ok:
        try:
            ok = _instant(row["transfer_updated_at"]) == _instant(EXPECTED_TIME)
        except (TypeError, ValueError):
            ok = False
    return _result(ok, f"target={dict(row) if row else None}")


def check_formal_reason(ws):
    with _db(ws, "sz_medical_aid_settlement") as con:
        row = con.execute(
            "SELECT calculation_note FROM claim_payment_layers "
            "WHERE claim_id = ? AND layer_type = 'INCLINED_AID'", (TARGET,),
        ).fetchone()
    note = _norm(row["calculation_note"] if row else "")
    required_groups = [
        ("人工复核",),
        ("广东省内规范转诊记录",),
        ("补充转诊单", "省内转诊备案凭证"),
        ("案件暂缓支付",),
    ]
    ok = row is not None and all(any(_norm(token) in note for token in group) for group in required_groups)
    return _result(ok, f"calculation_note={row['calculation_note'] if row else None}")


def check_inclined_layer_post_state(ws):
    with _db(ws, "sz_medical_aid_settlement") as con:
        row = con.execute(
            "SELECT eligibility_result, approval_status, approved_amount_fen "
            "FROM claim_payment_layers WHERE claim_id = ? AND layer_type = 'INCLINED_AID'",
            (TARGET,),
        ).fetchone()
    ok = row is not None and row["eligibility_result"] == "EVIDENCE_FAILED" and row["approval_status"] == "HELD" and row["approved_amount_fen"] == 0
    return _result(ok, f"inclined={dict(row) if row else None}")


def check_other_current_claims_unchanged(ws):
    with _db(ws, "sz_medical_aid_settlement") as con:
        rows = con.execute(
            "SELECT claim_id, record_version, is_current, transfer_compliance_code, "
            "transfer_updated_by, transfer_updated_at, claim_status "
            "FROM aid_claims WHERE claim_id <> ? ORDER BY claim_id", (TARGET,)
        ).fetchall()
    ok = len(rows) == 11 and all(
        row["record_version"] == 1 and row["is_current"] == 1 and
        row["transfer_updated_by"] is None and row["transfer_updated_at"] is None and
        row["claim_status"] == "REVIEW_PASSED" and
        row["transfer_compliance_code"] in {"COMPLIANT", "NOT_REQUIRED"}
        for row in rows
    )
    return _result(ok, f"other_current_claims={len(rows)} unchanged={ok}")


def check_audit_source_unchanged(ws):
    with _db(ws, "neusoft_medical_aid_audit") as con:
        case = con.execute(
            "SELECT review_status, approved_fund_fen, reviewer_id, reviewed_at, decision_version, is_current "
            "FROM review_cases WHERE review_case_id = 'RVC-SZ-202504-009'"
        ).fetchone()
        findings = con.execute(
            "SELECT COUNT(*) AS n FROM review_findings WHERE review_case_id = 'RVC-SZ-202504-009'"
        ).fetchone()["n"]
    ok = case is not None and tuple(case) == ("HELD", 0, EXPECTED_OPERATOR, "2025-05-06 15:27:58", "DV-202504-02", 1) and findings == 6
    return _result(ok, f"audit_case={dict(case) if case else None} findings={findings}")
